Эта ограниченная MPMC-очередь проходит тесты на x86, но повреждает данные на ARM-сервере. Напиши litmus-тест для herd7, демонстрирующий запрещённый исход в модели памяти C++20, запусти его, затем исправь очередь с использованием наиболее слабых порядков, которые всё ещё корректны, и покажи, что litmus-тест больше не находит этот исход.

```cpp
struct Cell { std::atomic<size_t> seq; T data; };
bool push(const T& v) {
  size_t pos = tail.load(std::memory_order_relaxed);
  for (;;) {
    Cell& c = buf[pos & mask];
    size_t seq = c.seq.load(std::memory_order_relaxed);
    intptr_t d = (intptr_t)seq - (intptr_t)pos;
    if (d == 0) { if (tail.compare_exchange_weak(pos, pos + 1, std::memory_order_relaxed)) { c.data = v; c.seq.store(pos + 1, std::memory_order_relaxed); return true; } }
    else if (d < 0) return false;
    else pos = tail.load(std::memory_order_relaxed);
  }
}
